const CS="CSS";
M(CS,"Which selector has the highest specificity?",["#nav .item","nav ul li a","ul.menu li.item","a:hover"],"IDs outrank classes/attributes/pseudo-classes, which outrank elements.");
M(CS,"What is the specificity of `:where(.card, #hero)`?",["0 (always zero)","1,0,0","0,1,0","It takes the highest argument"],":where() always contributes zero; :is() takes the most specific argument.");
M(CS,"What does `box-sizing: border-box` change?",["width/height include padding and border","margin is included in width","Only border is included","It disables padding"],"It makes sizing arithmetic predictable.");
M(CS,"Which situation causes vertical margin collapse?",["Adjacent block siblings' top/bottom margins in normal flow","Flex items' margins","Grid items' margins","Absolutely positioned elements' margins"],"Flex and grid items never collapse margins.");
M(CS,"A `position: sticky` header doesn't stick. The most likely cause is...",["An ancestor has overflow other than visible, or no top value is set","position: sticky only works on tables","z-index is too low","It needs display: flex"],"Sticky needs a threshold like top: 0 and a scroll container without clipping ancestors in between.");
M(CS,"Which of these creates a new stacking context?",["opacity less than 1","display: block","color: red","margin: auto"],"transform, filter, position+z-index, isolation: isolate and will-change also do.");
M(CS,"Why can an element with `z-index: 9999` still appear behind another?",["It's inside a lower stacking context","z-index has a max of 100","Only positive values work","z-index only works on divs"],"z-index only competes within the same stacking context.");
M(CS,"In `flex: 1`, what is the shorthand expansion?",["flex-grow 1, flex-shrink 1, flex-basis 0%","flex-grow 0, flex-shrink 1, flex-basis auto","flex-grow 1, flex-shrink 0, flex-basis auto","flex-grow 1 only"],"");
M(CS,"A flex child with long text overflows its container. The common fix is...",["min-width: 0 on the flex child","width: 100vw","display: block on the parent","overflow: visible"],"Flex items default to min-width: auto, preventing shrinking below content size.");
M(CS,"What does `1fr` mean in grid?",["One share of the remaining free space","1 pixel ratio","100% of the container","The smallest track"],"");
M(CS,"What does `repeat(auto-fit, minmax(200px, 1fr))` achieve?",["A responsive grid with as many 200px+ columns as fit, with no media queries","A fixed 200px grid","A single column","Overlapping columns"],"auto-fit collapses empty tracks; auto-fill keeps them.");
M(CS,"What does `clamp(1rem, 2vw + 0.5rem, 2rem)` return?",["A fluid value between 1rem and 2rem","Exactly 2vw","Always 1rem","The average of the three"],"clamp(min, preferred, max).");
M(CS,"What is a container query?",["Styles based on the size of a parent container, not the viewport","A query for container images","A media query for printers","A JS API"],"Use container-type: inline-size on the parent and @container in the child.");
M(CS,"What does the `:has()` selector enable?",["Selecting a parent based on its descendants","Selecting siblings only","Matching pseudo-elements","Matching media types"],"E.g. form:has(:invalid).");
M(CS,"What does `@layer` control?",["Cascade order independent of selector specificity","Z-index stacking","Image layers","Print layout"],"Unlayered styles beat layered ones, and later layers beat earlier ones.");
M(CS,"Which units are relative to the root font size?",["rem","em","ch","vh"],"em is relative to the element's (or parent's) font size, rem to the root.");
M(CS,"Why prefer `100dvh` over `100vh` on mobile?",["It accounts for dynamic browser toolbars","It is faster","It ignores scrollbars","It's required for flex"],"100vh can be larger than the visible area when the URL bar is showing.");
M(CS,"Which properties can the browser animate cheaply on the compositor?",["transform and opacity","width and height","top and left","margin and padding"],"Animating layout properties triggers reflow on every frame.");
M(CS,"What does `display: contents` do?",["Removes the element's box but keeps its children in the layout","Hides the element and its children","Makes element inline","Creates a grid"],"Be careful: it historically had accessibility bugs for buttons and tables.");
M(CS,"A `position: fixed` element behaves like absolute inside a parent. Why?",["The ancestor has transform, filter or perspective","Fixed is invalid in flex","The parent is overflow: hidden","The parent has z-index"],"Those properties create a containing block for fixed descendants.");
M(CS,"What's the difference between `display: none` and `visibility: hidden`?",["none removes from layout and accessibility tree; hidden keeps the space","They are identical","hidden removes the box","none keeps space"],"");
M(CS,"What do CSS custom properties do that preprocessor variables can't?",["Resolve at runtime, inherit, and be changed via JS or media queries","Compile faster","Work in IE only","Support math at build time only"],"");
M(CS,"What does `currentColor` refer to?",["The computed value of the `color` property","The last used color","The page's theme colour","A system colour"],"Useful for icons that inherit text colour.");
M(CS,"What does `prefers-reduced-motion: reduce` indicate?",["The user asked the OS to minimise animation","The device is low power","The network is slow","The tab is hidden"],"");
M(CS,"What is the purpose of `aspect-ratio`?",["Reserve a box with a given ratio, preventing layout shift","Crop images","Resize fonts","Control zoom"],"");
M(CS,"What does `object-fit: cover` do on an image?",["Fills the box, cropping as needed while keeping the ratio","Stretches to fit","Shrinks to fit entirely","Repeats the image"],"");
M(CS,"What is a Block Formatting Context (BFC) useful for?",["Containing floats and preventing margin collapse","Enabling grid","Triggering GPU","Loading fonts"],"overflow other than visible, display: flow-root, flex/grid items create BFCs.");
M(CS,"What does `content-visibility: auto` do?",["Skips rendering work for off-screen content","Hides content permanently","Lazy loads images only","Enables SSR"],"Pair it with contain-intrinsic-size to avoid scrollbar jumps.");
M(CS,"Which CSS feature lets nested grids align to the parent's tracks?",["subgrid","grid-auto-flow","grid-template-areas","place-items"],"");
M(CS,"What's the benefit of logical properties like `margin-inline-start`?",["They adapt to writing direction (LTR/RTL)","They're faster","They override !important","They're only for print"],"");
M(CS,"What does `@supports (display: grid)` do?",["Applies rules only if the browser supports the feature","Polyfills grid","Disables grid","Imports styles"],"");
M(CS,"What does `scroll-snap-type` do?",["Makes scroll containers settle on snap points","Hides scrollbars","Animates scroll","Locks scrolling"],"");
M(CS,"With `!important` declarations inside cascade layers, which layer wins?",["The earlier layer (order is reversed for important)","The later layer","Unlayered always","They tie"],"Important declarations invert the layer precedence.");
M(CS,"Which BEM class name is a modifier?",["button--primary","button__icon","button-primary-icon","btn.primary"],"Block__element--modifier.");
M(CS,"What is the main trade-off of utility-first CSS like Tailwind?",["Markup verbosity vs consistent tokens, small CSS and no naming","No design constraints","Slow runtime","No purge possible"],"");
M(CS,"What does `will-change: transform` do, and why use it sparingly?",["Hints the browser to promote a layer, which costs memory","Makes animations free","Fixes layout","Disables repaint"],"");
M(CS,"What is the CSS `isolation: isolate` used for?",["Creating a stacking context without other side effects","Isolating fonts","Disabling inheritance","Creating Shadow DOM"],"");
M(CS,"Which CSS makes a smooth, accessible scroll to anchors?",["scroll-behavior: smooth with a reduced-motion guard","JS only","animation: scroll","overflow: smooth"],"");
S(CS,"Which properties trigger layout (reflow) when changed?",["width","margin","font-size","top"],["opacity","transform","color"],"transform and opacity are compositor-only; color triggers paint only.");
S(CS,"Which properties create a stacking context?",["opacity < 1","transform","position fixed","isolation: isolate"],["margin","color","display: inline"],"");
S(CS,"Which techniques centre a box both ways?",["display:grid; place-items:center","display:flex; justify-content:center; align-items:center","position:absolute; inset:0; margin:auto (with fixed size)"],["text-align:center on a block","margin: 0 auto alone for vertical"],"");
S(CS,"Which values of `position` make an element a containing block for absolutely positioned children?",["relative","absolute","fixed","sticky"],["static"],"");
S(CS,"Which are true of CSS custom properties?",["They inherit by default","They can be redefined at any scope","They are accessible from JS via getComputedStyle"],["They cannot be used in calc()","They only work in :root"],"");
S(CS,"Which help prevent layout shift (CLS)?",["Setting width/height or aspect-ratio on images","Reserving space for ads/embeds","font-display with metric-matched fallbacks"],["Inserting banners above content after load","Lazy loading without dimensions"],"");
W(CS,"Explain the CSS box model and the effect of `box-sizing`.",[["content","padding","border","margin"],["border-box","content-box"],["width","include"]],"Each element is a box of content, padding, border and margin. With content-box, width/height set only the content; with border-box they include padding and border, which makes component sizing predictable. Most resets set border-box globally.");
W(CS,"How does CSS specificity and the cascade determine which rule wins?",[["origin","importance","important","layer"],["specificity","id","class"],["order","source order","last"],["inline"]],"The cascade ranks by origin/importance (including !important and layers), then specificity (inline, IDs, classes/attributes/pseudo-classes, elements) then source order. Keep specificity low, use layers/where() and avoid !important.");
W(CS,"Flexbox vs Grid: when do you choose each?",[["one-dimensional","1d","single axis","row or column","one dimension"],["two-dimensional","2d","rows and columns","both axes","two dimensions"],["content-driven","layout-driven","component","page layout","alignment"]],"Flexbox is one-dimensional and content-driven, ideal for toolbars, nav, and aligning items in a row/column. Grid is two-dimensional and layout-driven, ideal for page layouts and card grids where rows and columns align. They combine well.");
W(CS,"How would you build a responsive layout strategy for a large app?",[["mobile-first","mobile first"],["media quer","container quer"],["fluid","clamp","relative units","rem"],["breakpoint","token"],["grid","flex"]],"Start mobile-first with fluid units (rem, clamp, fr), use grid/flex with auto-fit/minmax, add few content-based breakpoints, prefer container queries for components, define spacing/typography tokens, test on real devices and handle touch targets and safe areas.");
W(CS,"What causes Cumulative Layout Shift and how do you fix it?",[["dimension","width","height","aspect-ratio","reserve","placeholder"],["font","font-display","fallback","swap"],["ad","embed","dynamic","inject","banner"],["transform","animation"]],"Unsized images/iframes, late-loading fonts, injected banners/ads and layout-affecting animations. Fix by reserving space (width/height, aspect-ratio, min-height), using metric-compatible font fallbacks and preload, inserting content below the fold or in reserved slots, and animating with transform.");
W(CS,"How would you structure CSS in a large codebase?",[["module","scoped","css modules","css-in-js","utility","tailwind","bem"],["token","variable","design system","custom propert"],["layer","specificity","cascade"],["naming","convention","lint","stylelint"]],"Pick one scoping strategy (CSS Modules, utility classes, or BEM), centralise tokens as custom properties, use @layer to order resets/base/components/utilities, keep specificity flat, lint with stylelint and avoid global overrides.");
W(CS,"How do you implement dark mode properly?",[["custom propert","variable","token"],["prefers-color-scheme","media"],["data-theme","class","attribute","toggle","user choice"],["color-scheme","flash","localstorage","persist"]],"Define colour tokens as CSS variables, redefine them under prefers-color-scheme and a data-theme attribute for manual override, set color-scheme so native controls follow, persist the choice and apply it before first paint to avoid a flash.");
W(CS,"Explain how stacking contexts work and how you'd debug a z-index problem.",[["stacking context"],["parent","ancestor"],["opacity","transform","position","isolation"],["devtools","3d view","layers","inspect"]],"z-index only orders elements within the same stacking context. A parent that creates one (opacity, transform, position with z-index, isolation) traps its children. To debug, walk up the ancestors in DevTools to find which creates a context, then restructure, move to a portal, or use isolation deliberately.");

// ---------- HTML & Accessibility ----------
const HA="HTML & A11y";
M(HA,"Which element should you use for an action that doesn't navigate (e.g. open a menu)?",["<button>","<a href='#'>","<div onclick>","<span role='link'>"],"Buttons give keyboard activation, focus and semantics for free.");
M(HA,"What is the correct use of `alt` text for a decorative image?",["An empty alt attribute (alt='')","Omit the attribute","alt='image'","alt='decorative image'"],"Empty alt hides the image from screen readers; a missing alt often leads to reading the filename.");
M(HA,"What contrast ratio does WCAG AA require for normal text?",["4.5:1","3:1","7:1","2:1"],"Large text and UI components require 3:1; AAA normal text is 7:1.");
M(HA,"What does `aria-live='polite'` do?",["Announces updates to the region when the user is idle","Interrupts immediately","Hides the region","Makes it focusable"],"assertive interrupts; use sparingly.");
M(HA,"What is the first rule of ARIA?",["Use native HTML elements when possible","Always add role attributes","Use aria-label on everything","ARIA replaces HTML"],"No ARIA is better than bad ARIA.");
M(HA,"When a modal dialog opens, what should happen to focus?",["Move focus into the dialog, trap it there, and return it to the trigger on close","Keep focus on the page","Focus the browser address bar","Disable focus entirely"],"The native <dialog> element with showModal() does most of this for you.");
M(HA,"What does `tabindex='0'` do?",["Makes an element focusable in natural tab order","Removes it from tab order","Focuses it first","Makes it hidden"],"tabindex='-1' makes it programmatically focusable only; positive values are an anti-pattern.");
M(HA,"What's the difference between `defer` and `async` on scripts?",["defer runs in order after parsing; async runs as soon as it's loaded, in any order","They are identical","async preserves order","defer blocks parsing"],"");
M(HA,"What does `<link rel='preload'>` do?",["Fetches a critical resource early with high priority","Navigates to a page early","Caches the page forever","Prefetches the next page at idle"],"prefetch is for likely future navigations at low priority.");
M(HA,"What does `loading='lazy'` do on an image?",["Defers loading until near the viewport","Loads it after the page's onload","Lowers quality","Blocks rendering"],"Don't lazy-load the LCP image.");
M(HA,"Which attributes provide responsive image candidates?",["srcset and sizes","src and alt","media and type","data-src"],"<picture> adds art direction and format switching.");
M(HA,"Which HTML element best conveys the main navigation landmark?",["<nav>","<div class='nav'>","<menu>","<ul>"],"");
M(HA,"How should a form input be associated with its label?",["<label for='id'> matching the input id or wrapping the input","placeholder only","title attribute only","aria-hidden label"],"Placeholders disappear and are not a replacement for labels.");
M(HA,"What does the `inert` attribute do?",["Makes an element and its subtree non-interactive and hidden from assistive tech","Makes it read-only","Dims it visually","Disables only buttons"],"");
M(HA,"Which `rel` should accompany `target='_blank'` historically for safety?",["noopener","nofollow","preload","external"],"Modern browsers imply noopener, but it's still good practice for older ones.");
M(HA,"What is Shadow DOM mainly for?",["Encapsulating a component's markup and styles","Hiding content from SEO","Faster rendering","Server rendering"],"");
M(HA,"What does the `<template>` element do?",["Holds inert HTML that isn't rendered until cloned","Renders a server template","Defines a web component","Imports another page"],"");
M(HA,"Which is the best element for a disclosure widget with no JS?",["<details> and <summary>","<div hidden>","<dialog>","<section>"],"");
M(HA,"What does the `popover` attribute provide?",["Top-layer, light-dismiss overlays with declarative triggers","CSS tooltips","Modal focus trapping","A JS polyfill"],"");
M(HA,"What does `fetchpriority='high'` do on an image?",["Hints the browser to prioritise the fetch (e.g. LCP image)","Preloads the whole page","Makes the image load synchronously","Disables caching"],"");
M(HA,"A screen reader user tabs to a custom dropdown built from divs. What's missing?",["Roles, states and keyboard handling (e.g. listbox, aria-expanded, arrow keys)","Only colour contrast","More padding","A tooltip"],"Prefer native <select> or an accessible headless library.");
M(HA,"What does `aria-hidden='true'` do?",["Removes the element from the accessibility tree but not from the screen","Hides visually","Disables the element","Makes it inert"],"Never put it on focusable elements.");
M(HA,"What is the purpose of a 'skip to content' link?",["Let keyboard users bypass repeated navigation","SEO","Faster paint","Improve screen reader language"],"");
M(HA,"Which heading structure is best?",["One h1, with nested levels without skipping","Only h1 tags","Use h4 for style","Headings are decorative"],"Style with CSS, structure with HTML.");
M(HA,"What does `lang='en'` on <html> affect?",["Screen reader pronunciation, hyphenation and spell-check","Only SEO","Only fonts","Nothing"],"");
M(HA,"Which input type shows a numeric keypad on mobile and still allows leading zeros (e.g. ZIP)?",["inputmode='numeric' on a text input","type='number'","type='tel' only","type='range'"],"type=number is for quantities and strips/changes leading zeros and formatting.");
M(HA,"What does `autocomplete='one-time-code'` help with?",["SMS OTP autofill","Password saving","Address entry","Credit card entry"],"");
M(HA,"What is `prefers-reduced-motion` best paired with?",["Disabling or shortening non-essential animation","Switching language","Downloading smaller images","Changing contrast"],"");
S(HA,"Which elements are focusable by default?",["<button>","<a href>","<input>","<select>"],["<div>","<span>","<p>"],"");
S(HA,"Which hide content from screen readers?",["display: none","visibility: hidden","aria-hidden='true'","the hidden attribute"],["A visually-hidden (sr-only) class","opacity: 0 with no other change"],"sr-only hides visually but remains in the accessibility tree.");
S(HA,"The four WCAG principles (POUR) are:",["Perceivable","Operable","Understandable","Robust"],["Responsive","Performant","Secure"],"");
S(HA,"Which are good practices for accessible forms?",["Associate labels with inputs","Describe errors in text and link via aria-describedby","Use autocomplete tokens","Don't rely on colour alone to show errors"],["Use placeholders instead of labels","Disable paste in password fields"],"");
S(HA,"Which improve keyboard accessibility?",["Visible focus indicators","Logical tab order","Using native interactive elements","Skip links"],["outline: none with no replacement","Positive tabindex values"],"");
S(HA,"Which are valid ways to defer non-critical resource loading?",["defer on scripts","loading='lazy' on below-the-fold images","dynamic import()","rel='preload' for non-critical items"],["Inline all scripts","document.write"],"Preloading everything defeats prioritisation.");
W(HA,"How do you build an accessible modal dialog?",[["role","dialog","aria-modal","showmodal"],["focus"],["trap","inert"],["escape","esc"],["return","restore","trigger"],["label","aria-labelledby"]],"Use <dialog>.showModal() or role='dialog' with aria-modal and a label. Move focus into the dialog, trap focus (or make the background inert), close on Escape, lock background scroll, and return focus to the trigger on close.");
W(HA,"What is semantic HTML and why does it matter?",[["meaning","semantic"],["accessib","screen reader","assistive"],["seo","search"],["maintain","landmark","built-in","keyboard"]],"Semantic elements (nav, main, article, button, etc.) convey meaning and built-in behaviour to browsers, assistive tech and search engines. They provide keyboard support and landmarks for free, improve SEO and maintainability.");
W(HA,"How would you test and audit a page's accessibility?",[["axe","lighthouse","wave","eslint-plugin-jsx-a11y"],["keyboard","tab"],["screen reader","voiceover","nvda","jaws"],["contrast","zoom","200%","reduced motion"],["manual","ci","automated"]],"Combine automated tools (axe, Lighthouse, linting, CI) with manual testing: keyboard only navigation, screen reader passes (VoiceOver/NVDA), contrast and zoom/reflow checks, reduced motion and real user testing. Automated tools catch roughly a third of issues.");
W(HA,"Explain responsive images and when to use `srcset`, `sizes` and `<picture>`.",[["srcset","resolution","density","width descriptor"],["sizes"],["picture","art direction","format","avif","webp"],["bandwidth","performance","lcp"]],"srcset offers multiple resolutions/widths and sizes tells the browser the rendered width so it can pick the best candidate. <picture> handles art direction and format fallbacks (AVIF/WebP/JPEG). Together they save bandwidth and improve LCP.");
W(HA,"What are Web Components and when would you choose them?",[["custom element","customelements"],["shadow dom","shadow"],["template","slot"],["framework-agnostic","design system","interop","reuse"]],"Web Components combine Custom Elements, Shadow DOM and templates/slots to create encapsulated reusable elements that work in any framework. They suit design systems shared across stacks, with trade-offs around SSR, styling and form integration.");
W(HA,"How should focus be managed in a single-page app after route navigation?",[["focus"],["heading","h1","main","container"],["announce","aria-live","title","screen reader"],["scroll","restore"]],"After a route change, move focus to the new page's main heading or container, update document.title, announce the change via a live region, and restore scroll position appropriately; otherwise screen reader and keyboard users stay lost at the old position.");
// ---------- React ----------
const RC="React";
M(RC,"What happens if you omit the dependency array from `useEffect`?",["It runs after every render","It runs once","It never runs","It runs only on unmount"],"An empty array runs once on mount; a list runs when values change.");
M(RC,"Why are stable `key` props important in lists?",["They let React match items between renders to preserve state and DOM","They improve CSS","They are required for hooks","They sort the list"],"Avoid array indexes as keys when items can reorder or be inserted.");
M(RC,"What is the result?\n\nconst [n, setN] = useState(0);\nfunction add() { setN(n + 1); setN(n + 1); setN(n + 1); }",["n becomes 1","n becomes 3","n becomes 0","React throws"],"Each call uses the same stale n. Use setN(prev => prev + 1) for 3.");
M(RC,"What does `useMemo` do?",["Caches a computed value between renders until dependencies change","Memoises a component","Stores state","Runs after render"],"It is a performance hint, not a semantic guarantee.");
M(RC,"What does `useCallback(fn, deps)` return?",["A memoised function reference","A promise","A cached value","A ref"],"It is only helpful if a child is memoised or the function is a dependency.");
M(RC,"What does `React.memo` compare by default?",["Props, shallowly","State deeply","Context","The DOM"],"Inline objects and functions as props defeat it.");
M(RC,"Which change does NOT trigger a re-render?",["Mutating `ref.current`","Calling setState with a new value","Parent re-rendering","Context value change"],"Refs are escape hatches for values not used in rendering.");
M(RC,"What is the difference between `useEffect` and `useLayoutEffect`?",["useLayoutEffect runs synchronously after DOM mutation, before paint","useEffect runs before render","They are identical","useLayoutEffect runs on the server"],"Use layout effects to measure DOM and avoid flicker; prefer useEffect otherwise.");
M(RC,"Why do effects run twice on mount in development with StrictMode?",["To surface missing cleanup and impure logic","It's a bug","Because of HMR","To warm the cache"],"React mounts, unmounts and re-mounts to check resilience. It does not happen in production.");
M(RC,"What is a controlled input?",["Its value is driven by React state and updated via onChange","It uses a ref only","It has no value prop","It's disabled"],"Uncontrolled inputs keep state in the DOM.");
M(RC,"What does changing a component's `key` do?",["Remounts it, resetting its state","Updates props","Triggers an effect only","Does nothing"],"A handy way to reset form state when an entity id changes.");
M(RC,"What is the purpose of the cleanup function returned from `useEffect`?",["Unsubscribe or cancel work before the next effect or unmount","Run on mount","Clear state","Return a value"],"");
M(RC,"What is a stale closure in hooks?",["A callback capturing outdated state or props from a previous render","A memory leak","A circular import","An unmounted component"],"Fix with correct deps, functional updates or refs.");
M(RC,"What does `useReducer` suit best?",["Complex state transitions with several related values","Simple booleans","Reading DOM","Fetching data"],"");
M(RC,"What does the Rules of Hooks forbid?",["Calling hooks conditionally or in loops","Using more than one hook","Using hooks in custom hooks","Using hooks with TypeScript"],"Hooks rely on call order being identical between renders.");
M(RC,"What is `useTransition` for?",["Marking state updates as non-urgent so input stays responsive","CSS animations","Route changes only","Server rendering"],"");
M(RC,"What does `useDeferredValue` do?",["Provides a lagging copy of a value to defer expensive updates","Delays network requests","Debounces forever","Caches API calls"],"");
M(RC,"What can't an error boundary catch?",["Errors in event handlers and async code","Render errors","Lifecycle errors","Errors in child components"],"Use try/catch for event handlers. Error boundaries are class components (or via libraries).");
M(RC,"What do React portals do?",["Render children into a different DOM node while keeping the React tree","Move state between components","Server-render content","Lazy load components"],"Useful for modals, tooltips and popovers.");
M(RC,"What does `React.lazy` with `Suspense` provide?",["Code-splitting of components with a fallback while loading","Server components","Memoisation","Global state"],"");
M(RC,"What is `useId` for?",["Stable unique IDs consistent across server and client","Keys in lists","Generating random numbers","Referencing DOM nodes"],"");
M(RC,"Which hook subscribes to an external store safely with concurrent rendering?",["useSyncExternalStore","useEffect with setState","useMemo","useRef"],"It prevents tearing.");
M(RC,"In React Server Components, which can a server component NOT do?",["Use state or effects","Fetch data directly","Render client components","Read from a database"],"Interactivity lives in 'use client' components.");
