const CD="Coding";
W(CD,"Write a debounce(fn, delay) function. Describe how it works.",[["settimeout"],["cleartimeout","clear"],["closure","timer","timeout id","timerid"],["apply","args","...args","this"]],"function debounce(fn, delay){ let t; return function(...args){ clearTimeout(t); t = setTimeout(() => fn.apply(this, args), delay); }; } It keeps a timer in a closure, resets it on every call, and invokes fn only after delay ms with no new calls. Add leading/trailing options and cancel() for production.");
W(CD,"Write a throttle(fn, limit) function and explain it.",[["limit","interval","delay"],["last","timestamp","date.now","flag","inthrottle","timer"],["ignore","skip","drop"],["apply","args","trailing"]],"function throttle(fn, limit){ let last = 0; return function(...args){ const now = Date.now(); if (now - last >= limit){ last = now; fn.apply(this, args); } }; } Calls inside the window are ignored; add a trailing call for completeness.");
W(CD,"Implement a function that flattens a nested array without using Array.prototype.flat.",[["recursion","recursive","reduce"],["isarray","array.isarray"],["concat","push","spread"],["depth","stack","iterative"]],"const flatten = (arr) => arr.reduce((acc, x) => Array.isArray(x) ? acc.concat(flatten(x)) : acc.concat(x), []); An iterative version uses an explicit stack to avoid recursion limits, and a depth parameter supports flat(depth).");
W(CD,"Implement a simple event emitter (on, off, emit, once).",[["map","object","listeners","handlers"],["on","subscribe"],["off","unsubscribe","remove"],["emit","trigger","dispatch"],["once","wrapper"]],"class Emitter { #h = new Map(); on(e, f){ (this.#h.get(e) ?? this.#h.set(e, new Set()).get(e)).add(f); return () => this.off(e, f); } off(e, f){ this.#h.get(e)?.delete(f); } once(e, f){ const w = (...a) => { this.off(e, w); f(...a); }; this.on(e, w); } emit(e, ...a){ this.#h.get(e)?.forEach(f => f(...a)); } }");
W(CD,"Implement a memoize function for single-argument and multi-argument functions.",[["map","cache","object"],["key","json.stringify","join","args"],["has","in cache","hit"],["closure","return a function","returns a function"]],"function memoize(fn){ const cache = new Map(); return (...args) => { const key = JSON.stringify(args); if (cache.has(key)) return cache.get(key); const v = fn(...args); cache.set(key, v); return v; }; } Caveats: key serialisation cost, object identity, unbounded growth (use an LRU) and impure functions.");
W(CD,"Implement a deepClone function. What cases must it handle?",[["recursion","recursive"],["array","object"],["date","map","set","regexp"],["circular","weakmap","cycle"],["structuredclone"]],"Handle primitives, arrays, plain objects, Date, Map, Set, RegExp and circular references (track visited in a WeakMap), recursing over own keys. In practice call structuredClone, noting it can't clone functions.");
W(CD,"Write a function to run async tasks with a concurrency limit.",[["queue","pool","index"],["promise","async","await"],["limit","concurrency","workers"],["results","order","settled","error"]],"Create `limit` workers that each pull the next task index from a shared counter until tasks are exhausted, await each task and store results by index, then await Promise.all(workers). Handle errors per task or fail fast, depending on needs.");
W(CD,"Implement a retry(fn, retries, delay) with exponential backoff.",[["try","catch"],["delay","timeout","sleep","wait"],["exponential","* 2","backoff","**","pow"],["jitter","attempt","retries","throw","last"]],"async function retry(fn, n = 3, d = 200){ for (let i = 0; ; i++){ try { return await fn(); } catch (e){ if (i >= n) throw e; await new Promise(r => setTimeout(r, d * 2 ** i + Math.random() * 100)); } } } It retries with doubling delays plus jitter and rethrows the last error.");
W(CD,"How would you implement a promise-based sleep and a timeout wrapper for a promise?",[["settimeout"],["new promise","resolve"],["race","promise.race","abortsignal.timeout"],["reject","error","timeout"]],"const sleep = ms => new Promise(r => setTimeout(r, ms)); const withTimeout = (p, ms) => Promise.race([p, new Promise((_, rej) => setTimeout(() => rej(new Error('Timeout')), ms))]); Prefer AbortController/AbortSignal.timeout to actually cancel the work and clear the timer when done.");
W(CD,"Write a function that returns the unique values of an array, preserving order, and explain complexity.",[["set","new set"],["order","insertion"],["o(n)","linear"],["objects","reference","key","filter","indexof","o(n^2)","o(n²)"]],"const unique = a => [...new Set(a)]; It is O(n) and keeps first-seen order. For objects dedupe by a key (Map keyed by id). filter/indexOf is O(n²).");
W(CD,"Implement `Function.prototype.bind` (a simplified polyfill).",[["apply","call"],["this","context"],["args","arguments","concat","partial"],["return","new","closure"]],"Function.prototype.myBind = function(ctx, ...pre){ const fn = this; return function(...args){ return fn.apply(ctx, [...pre, ...args]); }; }; A full version also supports `new` by checking `this instanceof bound` and preserving the prototype.");
W(CD,"How would you write a function to check balanced brackets in a string?",[["stack"],["push","pop"],["map","pairs","opening","closing"],["empty","o(n)","linear"]],"Use a stack: push opening brackets, on a closing bracket pop and compare with the matching opener; fail on mismatch or empty stack; at the end the stack must be empty. O(n) time, O(n) space.");
W(CD,"Write a function to group an array of objects by a key (like Object.groupBy).",[["reduce","for","loop"],["key","accumulator","acc"],["array","push","create"],["object.groupby","groupby","map.groupby"]],"const groupBy = (xs, f) => xs.reduce((acc, x) => { (acc[f(x)] ??= []).push(x); return acc; }, {}); Modern runtimes provide Object.groupBy and Map.groupBy.");
W(CD,"Implement `Promise.all` or `Promise.race` from scratch.",[["new promise"],["resolve","reject"],["then","promise.resolve"],["count","index","first"]],"Promise.race: return new Promise((res, rej) => items.forEach(p => Promise.resolve(p).then(res, rej))); Promise.all: track a results array and counter, resolving when all fulfil and rejecting on the first rejection.");
W(CD,"Write a curry function that supports f(a)(b)(c) and f(a, b)(c).",[["length","arity"],["apply","spread","concat","args"],["recursion","recursive","return a function","returns a function"]],"const curry = fn => function c(...a){ return a.length >= fn.length ? fn.apply(this, a) : (...b) => c.apply(this, [...a, ...b]); }; It collects args until the original function's arity is met.");
W(CD,"Implement an LRU cache. Which data structures give O(1) operations?",[["map","hash"],["linked list","doubly","order","insertion"],["capacity","evict","least recently"],["o(1)","constant"]],"Use a Map (which preserves insertion order): on get, delete and re-set the key to mark it most recent; on set, if size exceeds capacity delete the first key (map.keys().next().value). Classic form uses a hash map plus a doubly linked list. Both give O(1) get and put.");
